      if (!this.set_.has(key))
        this.keys_.push(key);
      return this.set_.add(key);
    },

    has: function(key) {
      return this.set_.has(key);
    },

    delete: function(key) {
      this.keys_.splice(this.keys_.indexOf(key), 1);
      this.set_.delete(key);
